package polyrelay

import (
	"encoding/hex"
	"math/big"
	"testing"
)

// Vectors generated from py-sdk's calls.py (eth-abi) — the encoder output is
// load-bearing: it becomes the `data` the wallet signs and the relayer
// dispatches, so exact ABI parity is required.

// threeCalls mirrors the py vector generator's input.
func threeCalls() []TransactionCall {
	return []TransactionCall{
		{To: addrRepeat(0x11), Data: nil, Value: big.NewInt(0)},
		{To: addrRepeat(0x22), Data: []byte{0xaa, 0xbb, 0xcc}, Value: big.NewInt(1_000_000)},
		{To: addrRepeat(0x33), Data: []byte{0xde, 0xad, 0xbe, 0xef, 0xca, 0xfe}, Value: new(big.Int).Lsh(big.NewInt(1), 128)},
	}
}

func TestEncodeProxyCall(t *testing.T) {
	t.Parallel()
	const want = ""
	got, err := EncodeProxyCall(threeCalls())
	if err != nil {
		t.Fatalf("EncodeProxyCall: %v", err)
	}
	if hex.EncodeToString(got) != want {
		t.Fatalf("EncodeProxyCall = ...%s\nwant                          ...%s",
			hex.EncodeToString(got)[len(want)-12:], want[len(want)-12:])
	}
}

func TestEncodeSafeMultisendCall(t *testing.T) {
	t.Parallel()
	const want = ""
	got, err := EncodeSafeMultisendCall(threeCalls())
	if err != nil {
		t.Fatalf("EncodeSafeMultisendCall: %v", err)
	}
	if hex.EncodeToString(got) != want {
		t.Fatalf("EncodeSafeMultisendCall mismatch (len got=%d want=%d)", len(got), len(want)/2)
	}
}

func TestEncodeSingleCall(t *testing.T) {
	t.Parallel()
	single := []TransactionCall{
		{To: addrRepeat(0x44), Data: []byte{0xff}, Value: big.NewInt(5)},
	}
	const wantProxy = ""
	const wantSafe = ""

	gp, err := EncodeProxyCall(single)
	if err != nil {
		t.Fatalf("EncodeProxyCall single: %v", err)
	}
	if hex.EncodeToString(gp) != wantProxy {
		t.Fatalf("EncodeProxyCall single mismatch")
	}
	gs, err := EncodeSafeMultisendCall(single)
	if err != nil {
		t.Fatalf("EncodeSafeMultisendCall single: %v", err)
	}
	if hex.EncodeToString(gs) != wantSafe {
		t.Fatalf("EncodeSafeMultisendCall single mismatch")
	}
}

func TestEncodeRejectsEmpty(t *testing.T) {
	t.Parallel()
	if _, err := EncodeProxyCall(nil); err == nil {
		t.Fatal("EncodeProxyCall(nil): expected error, got nil")
	}
	if _, err := EncodeSafeMultisendCall(nil); err == nil {
		t.Fatal("EncodeSafeMultisendCall(nil): expected error, got nil")
	}
}

func TestEncodeRejectsNilValue(t *testing.T) {
	t.Parallel()
	calls := []TransactionCall{{To: addrRepeat(0x11), Data: nil, Value: nil}}
	if _, err := EncodeProxyCall(calls); err == nil {
		t.Fatal("EncodeProxyCall(nil value): expected error, got nil")
	}
	if _, err := EncodeSafeMultisendCall(calls); err == nil {
		t.Fatal("EncodeSafeMultisendCall(nil value): expected error, got nil")
	}
}
